<template>
  <section class="management-work mail-center"><div class="work-heading"><h2>Correos a las clientas</h2><button type="button" :disabled="loading" @click="load"><RefreshCw :size="18"/> Actualizar</button></div><p v-if="error" role="alert" class="work-error">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><p v-if="loading">Cargando correos…</p><template v-if="config[state]"><div class="mail-editor"><label>Momento del envío<select v-model="state" @change="previewHtml=''"><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label><label class="mail-toggle"><input v-model="config[state].enabled" type="checkbox"> Enviar este correo a la clienta</label><label>Mensaje adicional<textarea v-model.trim="config[state].note" rows="4" maxlength="800"></textarea></label><div class="mail-actions"><button type="button" :disabled="busy" @click="preview"><Eye :size="18"/> Vista previa</button><button class="work-primary" type="button" :disabled="busy" @click="save"><Save :size="18"/> Guardar correos</button></div></div><iframe v-if="previewHtml" title="Vista previa del correo con datos de ejemplo" class="mail-preview" sandbox="" :srcdoc="previewHtml"></iframe></template><h3>Historial de envío</h3><p v-if="!events.length && !loading">Todavía no hay correos registrados.</p><article v-for="event in events" :key="event.id" class="mail-history"><div><strong>BS-{{ String(event.pedido_id).padStart(4,'0') }}</strong><span>{{ labels[event.estado] || event.estado }}</span><small>{{ event.enviado ? 'Aceptado por el servidor de correo' : event.ultimo_error || 'Pendiente de envío' }} · {{ event.intentos }} intento(s)</small></div><button v-if="!event.enviado && current(event)" type="button" :disabled="busy" @click="retry(event)"><RotateCw :size="16"/> Reintentar</button></article></section>
</template>
<script setup>
import {onMounted,ref} from 'vue'
import {RefreshCw,Eye,Save,RotateCw} from 'lucide-vue-next'
import {managementApi} from '../../api/index.js'
const labels={pending_payment:'Pedido reservado',payment_submitted:'Comprobante recibido',paid:'Pago confirmado',shipped:'Pedido despachado',pickup_ready:'Listo para retiro',delivered:'Pedido entregado',cancelled:'Pedido cancelado'}
const state=ref('paid'),config=ref({}),events=ref([]),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),previewHtml=ref('')
const current=event=>event.estado===event.current_state || event.estado==='pickup_ready'&&event.current_state==='shipped'
async function load(){loading.value=true;error.value='';try{const {data}=await managementApi.mail();config.value=data.customization;events.value=data.events}catch(e){error.value=e.response?.data?.error || 'No pudimos cargar los correos.'}finally{loading.value=false}}
async function save(){busy.value=true;error.value='';message.value='';try{if(!config.value.paid.enabled&&!window.confirm('¿Desactivar la confirmación de pago por correo a la clienta? Los avisos al comercio no se modifican.'))return;const {data}=await managementApi.saveMail(config.value);config.value=data;message.value='Correos actualizados.'}catch(e){error.value=e.response?.data?.error || 'No pudimos guardar los correos.'}finally{busy.value=false}}
async function preview(){busy.value=true;error.value='';try{const {data}=await managementApi.previewMail({state:state.value,note:config.value[state.value].note});previewHtml.value=data.html}catch(e){error.value='No pudimos preparar la vista previa.'}finally{busy.value=false}}
async function retry(event){busy.value=true;error.value='';message.value='';try{await managementApi.retryMail(event.id);message.value='Correo aceptado para envío.';await load()}catch(e){error.value=e.response?.data?.error || 'No se pudo reintentar el correo.'}finally{busy.value=false}}
onMounted(load)
</script>
<style scoped>
.mail-center{border-top:1px solid var(--ad-border);padding-top:28px;margin-top:28px}.mail-editor{display:grid;gap:18px;max-width:720px}.mail-toggle{display:flex;align-items:center;gap:10px}.mail-toggle input{width:20px;height:20px}.mail-actions{display:flex;flex-wrap:wrap;gap:10px}.mail-preview{margin:24px 0;width:100%;max-width:760px;height:700px;border:1px solid var(--ad-border);background:white;border-radius:6px}.mail-history{display:flex;gap:16px;align-items:center;justify-content:space-between;padding:18px 0;border-bottom:1px solid var(--ad-border)}.mail-history>div{display:grid;gap:7px;min-width:0;overflow-wrap:anywhere}.mail-history span{font-size:14px}.mail-history small{color:var(--ad-muted);font-size:13px}.mail-center h3{font-size:18px;margin:30px 0 12px}@media(max-width:720px){.mail-history{align-items:stretch;flex-direction:column}.mail-actions>*{flex:1}.mail-preview{height:650px}}
</style>
